// SystemInit.jsx
import React, { useState } from 'react';
import './SystemInit.css';
import CompanyLogo from "../../../src/assets/gm_edited.png";

const SystemInit = () => {
  const [activeStep, setActiveStep] = useState(1);
  const [formData, setFormData] = useState({
    operatorName: 'Yunoya LTD',
    county: 'Midland',
    location: 'Permian Basin',
    material: 'Steel',
    type: 'Transmission',
  });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleNext = () => {
    if (activeStep < 3) setActiveStep(activeStep + 1);
  };

  const handlePrev = () => {
    if (activeStep > 1) setActiveStep(activeStep - 1);
  };

  return (
    <div className="init-container">
     

      {/* Main content */}
      <main className="init-main">
        {/* Top bar */}
        <div className="init-topbar">
          <div className="init-topbar-left">
            <i className="fas fa-chevron-left"></i>
            <span>SYSTEM INITIALIZATION</span>
          </div>
          <div className="init-topbar-right">
            <i className="fas fa-question-circle"></i>
          </div>
        </div>

        {/* Step indicator */}
        <div className="init-steps">
          <div className={`init-step ${activeStep === 1 ? 'active' : ''}`}>
            <span className="init-step-number">1</span>
            <span className="init-step-label">ASSET PROFILE</span>
          </div>
          <div className={`init-step ${activeStep === 2 ? 'active' : ''}`}>
            <span className="init-step-number">2</span>
            <span className="init-step-label">CONTACTS</span>
          </div>
          <div className={`init-step ${activeStep === 3 ? 'active' : ''}`}>
            <span className="init-step-number">3</span>
            <span className="init-step-label">COMPLIANCE</span>
          </div>
        </div>

        {/* Step content */}
        <div className="init-content">
          <h2 className="init-content-title">ASSET PROFILE</h2>
          <p className="init-content-sub">Configure your primary pipeline parameters.</p>

          <div className="init-form">
            <div className="init-form-group">
              <label className="init-label">OPERATOR NAME</label>
              <input
                type="text"
                name="operatorName"
                className="init-input"
                value={formData.operatorName}
                onChange={handleInputChange}
              />
            </div>

            <div className="init-form-row">
              <div className="init-form-group">
                <label className="init-label">COUNTY</label>
                <input
                  type="text"
                  name="county"
                  className="init-input"
                  value={formData.county}
                  onChange={handleInputChange}
                />
              </div>
              <div className="init-form-group">
                <label className="init-label">LOCATION</label>
                <input
                  type="text"
                  name="location"
                  className="init-input"
                  value={formData.location}
                  onChange={handleInputChange}
                />
              </div>
            </div>

            <div className="init-form-row">
              <div className="init-form-group">
                <label className="init-label">MATERIAL</label>
                <select
                  name="material"
                  className="init-select"
                  value={formData.material}
                  onChange={handleInputChange}
                >
                  <option value="Steel">Steel</option>
                  <option value="Plastic">Plastic</option>
                  <option value="Cast Iron">Cast Iron</option>
                  <option value="Copper">Copper</option>
                </select>
              </div>
              <div className="init-form-group">
                <label className="init-label">TYPE</label>
                <select
                  name="type"
                  className="init-select"
                  value={formData.type}
                  onChange={handleInputChange}
                >
                  <option value="Transmission">Transmission</option>
                  <option value="Distribution">Distribution</option>
                  <option value="Gathering">Gathering</option>
                </select>
              </div>
            </div>
          </div>

          <button className="init-proceed" onClick={handleNext}>
            PROCEED TO CONTACTS
            <i className="fas fa-arrow-right"></i>
          </button>
        </div>
      </main>
    </div>
  );
};

export default SystemInit;
